import {resetProgress,revisionKey} from './progress.js';
import {chapters,sectionLink,textbook,read,e} from './course.js';
const root=document.querySelector('#course');let query='';
const keys=['soma-inside-v1','soma-cell-studio-v1','soma-local-ai-v1','soma-resume-v1','soma-atlas-draft-v1','soma-cell-draft-v1','soma-tissue-studio-v1','soma-tissue-draft-v1'];
const orbital='<div class="orbital" aria-hidden="true"><i class="orbit"></i><i class="orbit"></i><i class="orbit"></i><span>EXPLORE · CONNECT · RECALL</span></div>';
function header(){return `<header class="course-top"><a class="logo" href="#/">soma<span style="color:#75eee2">.</span></a><nav aria-label="Course navigation"><a href="#/">Chapters</a><a href="#/review">Review & progress</a><a href="#/help">Help</a><button class="motion-button" id="motion">Effects ${read('soma-motion','on')==='off'?'off':'on'}</button></nav></header>`;}
function resume(){const r=read('soma-resume-v1');return r.url&&/^(atlas\.html#|chapter[34]\/#)/.test(r.url)?`<a class="pill-link primary" href="${e(r.url)}">Continue ${e(r.label)} →</a>`:'<a class="pill-link primary" href="#/chapter/1">Start with Chapter 1 →</a>';}
function library(){const found=chapters.filter(c=>(c.id+' '+c.title+' '+c.sections.flat().join(' ')).toLowerCase().includes(query.toLowerCase()));return `<section class="course-hero"><div><p class="eyebrow">YOUR ANATOMY & PHYSIOLOGY STUDIO</p><h1>Understand life.<br><span class="gradient-word">One discovery at a time.</span></h1><p>Explore the structures. Make sense of the processes. Build confidence with guided lessons and practice, organized around your textbook.</p><div class="resume">${resume()}<a href="#/review">Review your work ↗</a></div></div>${orbital}</section><div class="section-row"><h2>Your chapter library</h2><input class="search" id="chapter-search" type="search" aria-label="Find a chapter or topic" placeholder="Find a chapter or topic…" value="${e(query)}"></div><section class="chapter-grid">${found.map(c=>`<a class="chapter-card" href="#/chapter/${c.id}" style="--tone:${c.color}"><span class="chapter-number">CHAPTER 0${c.id}</span><h3>${e(c.short)}</h3><p>${e(c.description)}</p><span class="card-end"><span>${e(c.coverage)}</span><span>Explore →</span></span></a>`).join('')||'<p>No available chapter matches. Try “membrane,” “atoms,” or a chapter number.</p>'}</section><p class="course-note">Chapters 1–4 are available with the coverage shown. Future chapters will join this library as their activities are added.</p>`;}
function overview(c){return `<p class="breadcrumb"><a href="#/">Chapters</a> / Chapter ${c.id}</p><section class="course-hero"><div><p class="eyebrow">CHAPTER ${String(c.id).padStart(2,'0')} · OPENSTAX A&P 2e</p><h1 style="font-size:clamp(30px,3.4vw,48px)">${e(c.title)}</h1><p>${e(c.description)}</p><a class="pill-link primary" href="${sectionLink(c,c.sections[0])}">Start ${c.sections[0][0]} →</a></div>${orbital}</section><div class="chapter-layout"><section class="section-list" aria-label="Textbook sections">${c.sections.map(s=>`<a class="section-item" href="${sectionLink(c,s)}"><b>${s[0]}</b><span>${e(s[1])}<small>${c.studio?'Learn · Explore · Practice · Review':c.id===2?'Focused essentials + textbook section':s[2]==='foundations'?'Focused essentials + textbook section':'Interactive atlas + textbook section'}</small></span><span style="margin-left:auto">→</span></a>`).join('')}</section><aside class="overview-panel"><p class="eyebrow">BUILD YOUR UNDERSTANDING</p><h2>${c.studio?'See it. Explain it. Recall it.':'A clear starting point.'}</h2><p>${c.studio?'Six sections with lessons, diagrams, comparisons and process labs. Practice a section or test the chapter.':'These activities support the chapter. Sections have focused review cards; full dedicated lessons are still being developed.'}</p><a class="pill-link" href="${c.studio?`${c.studio}#exam`:`atlas.html#chapter/${c.id}/exam`}">Chapter ${c.id} exam →</a><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/${c.id}-introduction" target="_blank" rel="noopener">Read chapter in OpenStax ↗</a><a href="local-ai/?chapter=${c.id}&tool=tutor">Ask the local tutor →</a><a href="local-ai/?chapter=${c.id}&tool=quiz">Generate practice →</a>${c.id===1?'<a class="pill-link" href="atlas.html#chapter/1/section/1.6/body-regions/study">Body regions · interactive atlas →</a>':''}<a href="atlas.html#custom-exam">Build a custom exam ↗</a></aside></div>`;}
function review(){const a=Object.entries(read('soma-inside-v1').stats||{}).filter(([k])=>!k.startsWith('cells/')&&!k.startsWith('tissues/')).map(([,s])=>s),c=Object.values(read('soma-cell-studio-v1').stats||{}),t=Object.values(read('soma-tissue-studio-v1').stats||{}),all=[...a,...c,...t];return `<p class="eyebrow">RECALL IS A PRACTICE</p><h1>Your next step is clear.</h1><p class="course-note">Reviewed practice on this browser. A correct answer is evidence of recall, not a guarantee of mastery.</p><div class="review-stat"><article><strong>${all.length}</strong>Questions attempted</article><article><strong>${all.filter(s=>s.lastCorrect===true&&!s.assisted).length}</strong>Latest answer correct without help</article><article><strong>${all.filter(s=>s.lastCorrect===false||s.assisted).length}</strong>Missed or assisted</article></div><p class="course-note">Older atlas records kept totals, not latest outcomes, so they count as attempted only. Legacy Chapter 3 atlas records stay in backups, not added again to Cell Studio scores. AI practice is separate.</p><div class="chapter-grid">${chapters.map(ch=>`<a class="chapter-card" href="${ch.studio?`${ch.studio}#review`:`atlas.html#chapter/${ch.id}/review`}"><span class="chapter-number">CHAPTER ${ch.id}</span><h3>${e(ch.short)}</h3><p>Revisit questions and reconnect them to the concepts.</p><span class="card-end">Review chapter →</span></a>`).join('')}</div><div class="course-backup"><button class="course-button" id="export">Back up learning progress</button><label class="course-button">Restore backup <input id="restore" type="file" accept="application/json" hidden></label></div><details class="practice-customize"><summary>Reset learning progress</summary><p>Start fresh in Chapters 1–4. This clears scores, unfinished sessions and your Continue shortcut on this browser. AI conversations, downloaded models and display preferences are kept.</p><p>Back up your progress above first if you may want it later.</p><button class="course-button" id="reset-progress">Reset all chapter progress…</button></details><p id="backup-status" role="status"></p><p class="course-note">Backups include saved AI conversations. Keep them private. Browser and desktop progress do not automatically sync.</p>`;}
function help(){return `<p class="eyebrow">STUDY YOUR WAY</p><h1>A familiar path in every chapter.</h1><div class="chapter-layout"><section class="overview-panel"><h2>Learn → Explore → Practice → Review</h2><p>Choose a chapter, then a numbered textbook section. Learn explains the idea; Explore gives it a visual form; Practice helps you retrieve it; Review helps you improve.</p><p>Read textbook links open OpenStax in a new tab. Study without an account or AI installation.</p><p>Effects pauses decorative motion. Your system’s reduced-motion preference is always respected.</p><p>Progress stays on this browser/device. Back it up in Review & progress.</p></section><aside class="overview-panel"><h2>Optional local AI</h2><p>The tutor and generated quizzes support Chapters 1–4 using the selected section’s studio references. AI feedback can need correction.</p><a href="local-ai/">Set up your companion ↗</a><a href="local-ai/?tool=setup">Connect Ollama ↗</a><a href="atlas.html#sources">Sources & image credits ↗</a></aside></div>`;}
function render(){document.documentElement.dataset.motion=read('soma-motion','on');const route=location.hash.slice(1).split('/').filter(Boolean),c=chapters.find(x=>x.id===Number(route[1]));root.innerHTML=header()+`<main class="course-main" id="main">${route[0]==='chapter'&&c?overview(c):route[0]==='review'?review():route[0]==='help'?help():library()}<footer class="course-footer"><span>OpenStax A&P 2e · Educational adaptations CC BY-NC-SA 4.0</span><span>Learning stays on this device.</span></footer></main>`;document.querySelector('#motion').onclick=()=>{try{localStorage.setItem('soma-motion',JSON.stringify(read('soma-motion','on')==='on'?'off':'on'));}catch{}render();};const search=document.querySelector('#chapter-search');if(search)search.oninput=()=>{query=search.value;render();document.querySelector('#chapter-search').focus();};document.querySelector('#export')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify({format:'soma-course',version:1,data:Object.fromEntries(keys.map(k=>[k,read(k,null)]))},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='soma-learning-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});document.querySelector('#reset-progress')?.addEventListener('click',()=>{if(!confirm('Clear all Chapter 1–4 scores and unfinished sessions on this browser? You will need a backup to undo this. AI conversations and models are kept.'))return;try{resetProgress(localStorage);render();document.querySelector('#backup-status').textContent='Chapter progress reset. You can start fresh from the chapter library.';}catch{document.querySelector('#backup-status').textContent='Could not reset progress. Check browser storage permissions.';}});document.querySelector('#restore')?.addEventListener('change',async ev=>{try{const f=ev.target.files[0];if(!f||f.size>20_000_000)throw Error('Choose a Soma backup under 20 MB.');const b=JSON.parse(await f.text());if(b.format!=='soma-course'||b.version!==1||!b.data||typeof b.data!=='object')throw Error('Unsupported backup.');for(const k of keys)if(b.data[k]!=null&&(typeof b.data[k]!=='object'||Array.isArray(b.data[k])))throw Error('Invalid backup data.');if(!confirm('Replace saved learning records with those in this backup?'))return;for(const k of keys)if(b.data[k])localStorage.setItem(k,JSON.stringify(b.data[k]));localStorage.setItem(revisionKey,JSON.stringify(`${Date.now()}-restore`));render();document.querySelector('#backup-status').textContent='Backup restored.';}catch(err){document.querySelector('#backup-status').textContent=err.message;}});}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();
